CREATE OR REPLACE FUNCTION public.admin_invite_user_db_setup(p_user_id UUID, p_email TEXT, p_first_name TEXT, p_last_name TEXT, p_role TEXT, p_organization_id UUID, p_zone_id UUID DEFAULT NULL) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$$ BEGIN INSERT INTO public.profiles (user_id, email, first_name, last_name, organization_id, invitation_status, updated_at) VALUES (p_user_id, p_email, p_first_name, p_last_name, p_organization_id, 'pending', now()) ON CONFLICT (user_id) DO UPDATE SET email = EXCLUDED.email, first_name = EXCLUDED.first_name, last_name = EXCLUDED.last_name, organization_id = EXCLUDED.organization_id, updated_at = EXCLUDED.updated_at; INSERT INTO public.user_roles (user_id, role, organization_id, zone_id, updated_at) VALUES (p_user_id, COALESCE(p_role, 'representative'), p_organization_id, p_zone_id, now()) ON CONFLICT (user_id) DO UPDATE SET role = EXCLUDED.role, organization_id = EXCLUDED.organization_id, zone_id = EXCLUDED.zone_id, updated_at = EXCLUDED.updated_at; INSERT INTO public.user_roles_plain (user_id, role, organization_id, zone_id, updated_at) VALUES (p_user_id, COALESCE(p_role, 'representative'), p_organization_id, p_zone_id, now()) ON CONFLICT (user_id) DO UPDATE SET role = EXCLUDED.role, organization_id = EXCLUDED.organization_id, zone_id = EXCLUDED.zone_id, updated_at = EXCLUDED.updated_at; RETURN jsonb_build_object('success', true); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $$$;
